import React from 'react';
import { useForm } from 'react-hook-form';
import { TextField, Button, Box } from '@mui/material';
import { EditSettingsDto } from '../../types/api';

interface SettingsFormProps {
  onSubmit: (data: EditSettingsDto) => void;
  initialData?: EditSettingsDto;
}

export const SettingsForm: React.FC<SettingsFormProps> = ({ onSubmit, initialData }) => {
  const { register, handleSubmit, formState: { errors } } = useForm<EditSettingsDto>({
    defaultValues: initialData,
  });

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        <TextField
          label="API"
          {...register('api', { required: 'Api is required' })}
          error={!!errors.api}
          helperText={errors.api?.message}
        />
        <Button type="submit" variant="contained">
          Submit
        </Button>
      </Box>
    </form>
  );
};
