import React from 'react';
import { useForm } from 'react-hook-form';
import { TextField, Button, Box } from '@mui/material';
import { CreatePostDto } from '../../types/api';

interface PostFormProps {
  onSubmit: (data: CreatePostDto) => void;
  initialData?: CreatePostDto;
}

export const PostForm: React.FC<PostFormProps> = ({ onSubmit, initialData }) => {
  const { register, handleSubmit, formState: { errors } } = useForm<CreatePostDto>({
    defaultValues: initialData,
  });

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        <TextField
          label="Title"
          {...register('title', { required: 'Title is required' })}
          error={!!errors.title}
          helperText={errors.title?.message}
        />
        <TextField
          label="Content"
          multiline
          rows={4}
          {...register('content', { required: 'Content is required' })}
          error={!!errors.content}
          helperText={errors.content?.message}
        />
        <TextField
          label="User ID"
          type="number"
          {...register('user_id', {
            required: 'User ID is required',
            valueAsNumber: true
          })}
          error={!!errors.user_id}
          helperText={errors.user_id?.message}
        />
        <Button type="submit" variant="contained">
          Submit
        </Button>
      </Box>
    </form>
  );
};
