import React from 'react';
import { Typography, Box } from '@mui/material';
import { SettingsForm } from '../../components/settings/SettingsForm';
import { EditSettingsDto } from '../../types/api';

export const EditSettings: React.FC = () => {

  const settings: EditSettingsDto = {
    api: localStorage.getItem("api_url") || ""
  };

  const handleSubmit = (data: EditSettingsDto) => {
    localStorage.setItem("api_url", data.api)
    window.location.replace('/');
  };


  return (
    <Box>
      <Typography variant="h4" sx={{ mb: 4 }}>Edit Settings</Typography>
      <SettingsForm
        onSubmit={handleSubmit}
        initialData={settings ? {
          api: settings.api
        } : undefined}
      />
    </Box>
  );
};
