import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Typography, Box } from '@mui/material';
import { UserForm } from '../../components/users/UserForm';
import { userApi } from '../../services/api';
import { CreateUserDto } from '../../types/api';

export const EditUser: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data: user, isLoading, isError, error } = useQuery({
    queryKey: ['user', id],
    queryFn: () => userApi.getUser(Number(id)),
    enabled: !!id,
    staleTime: 5 * 60 * 1000, // Cache for 5 minutes
    retry: 2
  });

  const updateUserMutation = useMutation({
    mutationFn: (data: CreateUserDto) => userApi.updateUser(Number(id), data),
    onSuccess: () => {
      // Invalidate both the users list and the individual user
      queryClient.invalidateQueries({ queryKey: ['users'] });
      queryClient.invalidateQueries({ queryKey: ['user', id] });
      navigate('/users');
    },
    onError: (error) => {
      console.error('Failed to update user:', error);
      // You might want to add error notification here
    },
    retry: 2,
    retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),
  });

  const handleSubmit = (data: CreateUserDto) => {
    updateUserMutation.mutate(data);
  };

  if (isLoading) return <Typography>Loading...</Typography>;

  return (
    <Box>
      <Typography variant="h4" sx={{ mb: 4 }}>Edit User</Typography>
      <UserForm
        onSubmit={handleSubmit}
        initialData={user ? { name: user.name, email: user.email } : undefined}
      />
    </Box>
  );
};
