import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Typography, Box } from '@mui/material';
import { PostForm } from '../../components/posts/PostForm';
import { postApi } from '../../services/api';
import { CreatePostDto } from '../../types/api';

export const EditPost: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data: post, isLoading, isError, error } = useQuery({
    queryKey: ['post', id],
    queryFn: () => postApi.getPost(Number(id)),
    enabled: !!id, // Only fetch when id exists
    staleTime: 5 * 60 * 1000, // Cache for 5 minutes
    retry: 2
  });

  const updatePostMutation = useMutation({
    mutationFn: (data: CreatePostDto) => postApi.updatePost(Number(id), data),
    onSuccess: () => {
      // Invalidate both the posts list and the individual post
      queryClient.invalidateQueries({ queryKey: ['posts'] });
      queryClient.invalidateQueries({ queryKey: ['post', id] });
      navigate('/posts');
    },
    onError: (error) => {
      console.error('Failed to update post:', error);
      // You might want to add error notification here
    },
    retry: 2,
    retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),
  });

  const handleSubmit = (data: CreatePostDto) => {
    updatePostMutation.mutate(data);
  };

  if (isLoading) return <Typography>Loading...</Typography>;

  return (
    <Box>
      <Typography variant="h4" sx={{ mb: 4 }}>Edit Post</Typography>
      <PostForm
        onSubmit={handleSubmit}
        initialData={post ? {
          title: post.title,
          content: post.content,
          user_id: post.user_id
        } : undefined}
      />
    </Box>
  );
};
