import axios from 'axios';
import { User, Post, CreateUserDto, CreatePostDto } from '../types/api';

const api = axios.create({
  baseURL: localStorage.getItem("api_url")!,
});

export const userApi = {
  getUsers: async (page: number = 1, limit: number = 10): Promise<User[]> => {
    const response = await api.get(`/users?page=${page}&limit=${limit}`);
    return response.data;
  },

  getUser: async (id: number): Promise<User> => {
    const response = await api.get(`/users/${id}`);
    return response.data;
  },

  createUser: async (user: CreateUserDto): Promise<User> => {
    const response = await api.post('/users', user);
    return response.data;
  },

  updateUser: async (id: number, user: CreateUserDto): Promise<User> => {
    const response = await api.put(`/users/${id}`, user);
    return response.data;
  },

  deleteUser: async (id: number): Promise<void> => {
    await api.delete(`/users/${id}`);
  },
};

export const postApi = {
  getPosts: async (page: number = 1, limit: number = 10): Promise<Post[]> => {
    const response = await api.get(`/posts?page=${page}&limit=${limit}`);
    return response.data;
  },

  getPost: async (id: number): Promise<Post> => {
    const response = await api.get(`/posts/${id}`);
    return response.data;
  },

  createPost: async (post: CreatePostDto): Promise<Post> => {
    const response = await api.post('/posts', post);
    return response.data;
  },

  updatePost: async (id: number, post: CreatePostDto): Promise<Post> => {
    const response = await api.put(`/posts/${id}`, post);
    return response.data;
  },

  deletePost: async (id: number): Promise<void> => {
    await api.delete(`/posts/${id}`);
  },
};
